def is_prime(n):
    if n < 2:
        return False
    for i in range(2, int(n ** 0.5) + 1):
        if n % i == 0:
            return False
    return True

function debounce(fn, delay) {
  let timer = null;
  return function (...args) {
    clearTimeout(timer);
    timer = setTimeout(() => fn.apply(this, args), delay);
  };
}

WITH ranked AS (
  SELECT title, plays,
         RANK() OVER (PARTITION BY genre ORDER BY plays DESC) AS rk
  FROM tracks
)
SELECT title FROM ranked WHERE rk <= 3;

import time

def retry(times=3, wait=0.5):
    def deco(fn):
        def wrapper(*a, **kw):
            for i in range(times):
                try:
                    return fn(*a, **kw)
                except OSError:
                    time.sleep(wait * (2 ** i))
            raise
        return wrapper
    return deco
